Let $x\in\Hcal$ and $y\in\CC^{\dim\Hcal}$. Then we compute,
  \begin{align*}
   \ip{x}{R_e^*(y)}_{\Hcal} &= \ip{R_e(x)}{y}_{\CC^{\dim\Hcal}} = \sum_i\ip{R_e(x)_i}{y_i}_{\CC} = \sum_i\ip{\ip{e_i}{x}_{\Hcal}}{y_i}_{\CC}\\
   &= \sum_i\ip{x}{e_i}_{\Hcal}y_i = \sum_i\ip{x}{y_ie_i}_{\Hcal}=\ip{x}{R_e^{-1}(y)}_{\Hcal}.
  \end{align*}

So then we compute,
  \begin{align*}
   \phi^{\operatorname{r}}(x) &={\phi}^{\operatorname{r}}(a^*a-b^*b)\\
    &= {\phi(a^*a)}^*-{\phi(b^*b)}^*=\phi(a^*a)-\phi(b^*b).
  \end{align*}
  The last equality follows from $\phi$ being a positive map and both $a^*a$ and $b^*b$ being positive semi-definite.

So suppose $A$ is real. Now let $x\in{B}$. Then using Lemma \ref{Coalgebra.comul_mul}, we compute,
 \begin{align*}
  A(x^*x) &= (A \bullet A)m(x^*\otimes x)\\
  &= \sum_im(A\otimes A)(x^*u_i\otimes u_i^*x)\\
  &= \sum_iA(x^*u_i)A(u_i^*x)=\sum_i{A(u_i^*x)}^*A(u_i^*x) \geq0.
 \end{align*}
